const envelope = $json.body ?? {};
const type = typeof envelope.type === 'string' ? envelope.type : '';
const payload = envelope.payload && typeof envelope.payload === 'object' && !Array.isArray(envelope.payload) ? envelope.payload : {};
const envelopeValid = Boolean(envelope.id && envelope.tenantId && envelope.aggregateType && envelope.aggregateId && envelope.occurredAt && type);

if (envelopeValid && type === 'lead.qualified') {
  return [{ json: { route: 'leadQualified', eventId: envelope.id, envelope } }];
}

if (!envelopeValid || !['followup.requested', 'followup.due'].includes(type)) {
  return [{ json: { route: 'ignored', eventId: envelope.id ?? null, eventType: type || null, reason: envelopeValid ? 'event_type_not_handled' : 'invalid_envelope', envelope } }];
}

return [{
  json: {
    route: 'followup',
    eventId: envelope.id,
    eventType: type,
    tenantId: envelope.tenantId,
    jobId: payload.followUpJobId ?? payload.jobId ?? envelope.aggregateId,
    leadId: payload.leadId ?? '',
    runAt: payload.runAt ?? envelope.occurredAt,
    occurredAt: envelope.occurredAt,
    reason: payload.reason ?? '',
    envelope
  }
}];

const event = $('Normalizar e Validar Evento').item.json;
const lead = $json.data && typeof $json.data === 'object' && !Array.isArray($json.data) ? $json.data : null;
const templateName = String($env.META_FOLLOWUP_TEMPLATE_NAME ?? '').trim();
const languageCode = String($env.META_TEMPLATE_LANGUAGE ?? 'pt_BR').trim();
const allowlist = String($env.META_FOLLOWUP_TEMPLATE_ALLOWLIST ?? '').split(',').map((value) => value.trim()).filter(Boolean);
const to = String(lead?.phone ?? '').replace(/\D/g, '');
const dueTimestamp = Date.parse(String(event.runAt));
const eventTimestamp = Date.parse(String(event.occurredAt));
const lastInteractionTimestamp = Date.parse(String(lead?.lastInteractionAt ?? ''));
const followupIsDue = Number.isFinite(dueTimestamp) && dueTimestamp <= Date.now();
const hasNewInteraction = Number.isFinite(eventTimestamp) && Number.isFinite(lastInteractionTimestamp) && lastInteractionTimestamp > eventTimestamp;
const leadIsActive = lead?.status === 'ACTIVE';
const leadName = String(lead?.name ?? lead?.profile?.name ?? 'cliente').trim().slice(0, 120) || 'cliente';
const components = [{ type: 'body', parameters: [{ type: 'text', text: leadName }] }];

const validationErrors = [];
if (!event.leadId) validationErrors.push('missing_lead_id');
if (!lead) validationErrors.push('missing_lead_response');
if (!/^\d{10,15}$/.test(to)) validationErrors.push('invalid_phone');
if (!leadIsActive) validationErrors.push('lead_not_active');
if (hasNewInteraction) validationErrors.push('lead_interacted_after_scheduling');
if (!followupIsDue) validationErrors.push('followup_not_due');
if (!templateName) validationErrors.push('missing_template');
if (!allowlist.includes(templateName)) validationErrors.push('template_not_allowlisted');
if (!/^[a-z]{2}(?:_[A-Z]{2})?$/.test(languageCode)) validationErrors.push('invalid_language');

return [{ json: {
  followupAction: validationErrors.length === 0 ? 'send' : 'skip',
  validationErrors,
  eventId: event.eventId,
  eventType: event.eventType,
  tenantId: event.tenantId,
  jobId: event.jobId,
  leadId: event.leadId,
  to,
  templateName,
  languageCode,
  components
} }];
